runText('/* New Hope 7 — date, birthday, font choices and soul-winning journal v4.4.0 */\n(()=>{\'use strict\';\nconst L=(fa,en,hr)=>((localStorage.getItem(\'nh7_lang\')||\'en\')===\'fa\'?fa:(localStorage.getItem(\'nh7_lang\')||\'en\')===\'hr\'?hr:en);\nconst esc=value=>String(value??\'\').replace(/[&<>\'"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',"\'":\'&#39;\',\'"\':\'&quot;\'}[c]));\nconst KEY=\'nh7_soul_journal_v440\';\nfunction rows(){try{return JSON.parse(localStorage.getItem(KEY)||\'[]\')}catch(_){return[]}}\nfunction save(value){localStorage.setItem(KEY,JSON.stringify(value));window.dispatchEvent(new CustomEvent(\'nh7:progress-updated\'))}\nfunction formatDate(date=new Date()){const lang=localStorage.getItem(\'nh7_lang\')||\'en\';try{if(lang===\'fa\')return new Intl.DateTimeFormat(\'fa-IR-u-ca-persian\',{day:\'numeric\',month:\'long\',year:\'numeric\'}).format(date);return new Intl.DateTimeFormat(lang===\'hr\'?\'hr-HR\':\'en-GB\',{day:\'numeric\',month:\'long\',year:\'numeric\'}).format(date)}catch(_){return date.toLocaleDateString()}}\nfunction mountDate(){const brand=document.querySelector(\'.brand>div\');if(!brand)return;let node=document.getElementById(\'nh7HeaderDateV440\');if(!node){node=document.createElement(\'small\');node.id=\'nh7HeaderDateV440\';node.className=\'nh7-header-date-v440\';brand.appendChild(node)}const text=\'📅 \'+formatDate();if(node.textContent!==text)node.textContent=text}\nfunction enhanceFonts(){const options=[[\'naskh\',L(\'نسخ کتابی\',\'Naskh book\',\'Naskh\')],[\'kufi\',L(\'کوفی مدرن\',\'Modern Kufi\',\'Moderni Kufi\')],[\'serif\',L(\'سریف رسمی\',\'Classic serif\',\'Klasični serif\')],[\'modern\',L(\'مدرن\',\'Modern\',\'Moderni\')]],saved=window.NH7_APPEARANCE_V430?.read?.()||{};for(const select of document.querySelectorAll(\'[data-appearance="font"],#previewFont\')){for(const [value,label] of options)if(!select.querySelector(`option[value="${value}"]`))select.add(new Option(label,value));select.value=select.dataset.appearance===\'font\'?(saved.font||\'native\'):(saved.readerFont||select.value)}}\nfunction medal(count){if(count>=25)return\'🏆 \'+L(\'صیاد جان طلایی\',\'Golden Soul Winner\',\'Zlatni osvajač duša\');if(count>=10)return\'🥇 \'+L(\'خادم بشارت\',\'Gospel Servant\',\'Služitelj evanđelja\');if(count>=5)return\'🥈 \'+L(\'همراه جان\u200cها\',\'Soul Caregiver\',\'Skrbnik duša\');if(count>=1)return\'🌱 \'+L(\'اولین ثمره\',\'First Fruit\',\'Prvi plod\');return\'○ \'+L(\'هنوز موردی ثبت نشده\',\'No entry yet\',\'Još nema zapisa\')}\nasync function render(view,lang){const data=rows();view.innerHTML=`<section class="card nh7-souls-v440"><div class="nh7-souls-head"><div><h2>${L(\'جان\u200cهایی که به مسیح هدایت کرده\u200cام\',\'People I have led to Christ\',\'Osobe koje sam doveo Kristu\')}</h2><p>${L(\'یک دفتر شخصی برای ثبت دعا، پیگیری و شاگردسازی؛ این فهرست فقط برای خود شماست.\',\'A private journal for prayer, follow-up and discipleship.\',\'Privatni dnevnik za molitvu, praćenje i učeništvo.\')}</p></div><span class="nh7-souls-count">${data.length}</span></div><div class="notice"><strong>${medal(data.length)}</strong></div><form id="nh7SoulForm"><label>${L(\'نام شخص\',\'Name\',\'Ime\')}<input id="nh7SoulName" maxlength="80" required></label><label>${L(\'تاریخ دعای نجات\',\'Date of salvation prayer\',\'Datum molitve spasenja\')}<input id="nh7SoulDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>${L(\'مرحله پیگیری\',\'Follow-up stage\',\'Faza praćenja\')}<select id="nh7SoulStage"><option value="prayer">${L(\'دعای نجات انجام شد\',\'Salvation prayer completed\',\'Molitva spasenja završena\')}</option><option value="contact">${L(\'در حال پیگیری\',\'Follow-up in progress\',\'Praćenje u tijeku\')}</option><option value="church">${L(\'به جمع کلیسا متصل شد\',\'Connected to church\',\'Povezan s crkvom\')}</option><option value="discipleship">${L(\'در مسیر شاگردسازی\',\'In discipleship\',\'U učeništvu\')}</option></select></label><label>${L(\'یادداشت خصوصی\',\'Private note\',\'Privatna bilješka\')}<textarea id="nh7SoulNote" maxlength="600"></textarea></label><button class="primary-btn" type="submit">${L(\'ثبت و دریافت امتیاز خدمت\',\'Save and receive ministry points\',\'Spremi i primi bodove služenja\')}</button></form><div class="nh7-souls-list">${data.map(row=>`<article><div><strong>${esc(row.name)}</strong><small>${esc(row.date)} · ${esc(row.stageLabel||row.stage)}</small>${row.note?`<p>${esc(row.note)}</p>`:\'\'}</div><button type="button" data-delete-soul="${esc(row.id)}" aria-label="${L(\'حذف\',\'Delete\',\'Izbriši\')}">×</button></article>`).join(\'\')||`<p class="muted">${L(\'اولین نام را پس از دعای نجات ثبت کنید و برای پیگیری او دعا کنید.\',\'Add the first name after the salvation prayer and continue praying for follow-up.\',\'Dodajte prvo ime nakon molitve spasenja i nastavite moliti.\')}</p>`}</div></section>`;const form=document.getElementById(\'nh7SoulForm\');form.onsubmit=event=>{event.preventDefault();const id=crypto.randomUUID?.()||String(Date.now()),stage=document.getElementById(\'nh7SoulStage\'),row={id,name:document.getElementById(\'nh7SoulName\').value.trim(),date:document.getElementById(\'nh7SoulDate\').value,stage:stage.value,stageLabel:stage.options[stage.selectedIndex].text,note:document.getElementById(\'nh7SoulNote\').value.trim(),createdAt:new Date().toISOString()};if(!row.name||!row.date)return;const next=[row,...rows()];save(next);window.NH7_ADD_POINTS?.(25,next.length>=10?\'soul_winner_10\':next.length>=5?\'soul_winner_5\':\'soul_winner_1\',\'soul_\'+id);render(view,lang)};view.querySelectorAll(\'[data-delete-soul]\').forEach(button=>button.onclick=()=>{if(confirm(L(\'این مورد حذف شود؟\',\'Delete this entry?\',\'Izbrisati ovaj zapis?\'))){save(rows().filter(row=>row.id!==button.dataset.deleteSoul));render(view,lang)}})}\n// Local preview guarantee: once per account and local calendar year on this device.\n// Cross-device deduplication requires a staging-backed atomic account/year claim.\nfunction claimBirthday(profile,user,now=new Date(),storage=localStorage){\n const account=String(user?.id||\'\');if(!account)return false;\n const raw=String(profile.birthDate||profile.birthdate||profile.date_of_birth||profile.dob||\'\');\n const match=/^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(raw);if(!match)return false;\n const year=Number(match[1]),month=Number(match[2]),day=Number(match[3]);\n const date=new Date(0);date.setFullYear(year,month-1,day);date.setHours(0,0,0,0);\n if(year<1||date.getFullYear()!==year||date.getMonth()!==month-1||date.getDate()!==day||date>now)return false;\n if(now.getMonth()!==month-1||now.getDate()!==day)return false;\n const marker=\'nh7_birthday_seen_v2:\'+encodeURIComponent(account)+\':\'+now.getFullYear();\n try{if(storage.getItem(marker))return false;storage.setItem(marker,\'1\');return storage.getItem(marker)===\'1\'}catch(_){return false}\n}\nfunction birthday(){\n let user={},profile={};\n try{const session=JSON.parse(localStorage.getItem(\'nh7_user_session_v170\')||\'{}\');user=session.currentSession?.user||session.user||session.session?.user||{}}catch(_){}\n if(!user.id)return;\n // Do not use a previous account\'s locally cached registration.\n for(const key of [\'nh7_school_access\',\'nh7_user_profile\'])try{\n  const cached=JSON.parse(localStorage.getItem(key)||\'{}\');\n  const owner=cached.user_id||cached.userId;\n  const matches=owner?owner===user.id:(cached.email&&user.email&&String(cached.email).toLowerCase()===String(user.email).toLowerCase());\n  if(matches)profile={...profile,...cached};\n }catch(_){}\n profile={...profile,...user.user_metadata};\n if(!claimBirthday(profile,user))return;\n const icons=[\'★\',\'✦\',\'♥\',\'●\',\'🎉\',\'✨\'],particles=Array.from({length:42},(_,i)=>`<i style="--x:${-165+(i*67)%330}px;--delay:${(i%10)*.08}s;--spin:${180+(i%7)*75}deg">${icons[i%icons.length]}</i>`).join(\'\');const modal=document.createElement(\'div\');modal.className=\'nh7-birthday-v440\';modal.innerHTML=`<div><div class="nh7-birthday-particles" aria-hidden="true">${particles}</div><button type="button" aria-label="${L(\'بستن\',\'Close\',\'Zatvori\')}">×</button><span class="nh7-birthday-icon">🎂</span><h2>${L(\'تولدت مبارک!\',\'Happy Birthday!\',\'Sretan rođendan!\')}</h2><p>${L(\'تو برای خداوند بسیار باارزش هستی؛ آن\u200cقدر ارزشمند که عیسی مسیح جان خود را برای تو داد. خانواده New Hope 7 تولدت را تبریک می\u200cگوید و برای سالی پر از فیض، سلامتی و پیروزی دعا می\u200cکند.\',\'You are deeply precious to God—so precious that Jesus Christ gave His life for you. Your New Hope 7 family wishes you a happy birthday and prays for a year of grace, health and victory.\',\'Bogu si neizmjerno dragocjen — toliko dragocjen da je Isus Krist dao svoj život za tebe. Tvoja obitelj New Hope 7 želi ti sretan rođendan i moli za godinu milosti, zdravlja i pobjede.\')}</p><b>🎉 💚 🎂 💙 🎈 💚</b></div>`;document.body.appendChild(modal);modal.querySelector(\'button\').onclick=()=>modal.remove();setTimeout(()=>modal.remove(),16000)}\nlet timer=0;new MutationObserver(()=>{clearTimeout(timer);timer=setTimeout(()=>{mountDate();enhanceFonts()},50)}).observe(document.documentElement,{childList:true,subtree:true});document.addEventListener(\'DOMContentLoaded\',()=>{mountDate();enhanceFonts();setTimeout(birthday,900)});setInterval(mountDate,60000);\nwindow.NH7_SOUL_JOURNAL_V440={render,rows};\nwindow.NH7_BIRTHDAY_V440={claimBirthday};\n})();\n\n;\n/* Private preview reliability boot. Keeps enhancement modules mounted after route renders. */\nconst modules=()=>[window.NH7_AUDIO_CLASSIC_V400,window.NH7_AUDIO_SOCIAL_V430,window.NH7_BIBLE_QUICK_V430,window.NH7_APPEARANCE_V430,window.NH7_SHARE_LINKS_V431,window.NH7_STORE_REVIEW_V431,window.NH7_PROGRESS_V431].filter(Boolean);\nlet timer=0;\nfunction refresh(){if(timer)return;timer=setTimeout(()=>{timer=0;for(const feature of modules())try{feature.mount?.();feature.mountSettings?.();feature.patch?.()}catch(error){console.warn(\'[NH7 preview feature]\',error)}window.NH7_AUDIO_SOCIAL_V430?.patch?.()},80)}\nwindow.addEventListener(\'nh7:route-rendered\',refresh);\nwindow.addEventListener(\'hashchange\',refresh);window.addEventListener(\'popstate\',refresh);window.addEventListener(\'load\',refresh);refresh();\ndocument.addEventListener(\'click\',event=>{const button=event.target.closest?.(\'#enableNotify\');if(!button||!window.NH7_PRIVATE_PREVIEW)return;event.preventDefault();event.stopImmediatePropagation();let note=document.getElementById(\'nh7PreviewSettingsNote\');if(!note){note=document.createElement(\'p\');note.id=\'nh7PreviewSettingsNote\';note.className=\'notice\';button.insertAdjacentElement(\'afterend\',note)}note.textContent=\'در نسخه خصوصی، ارسال اعلان واقعی عمداً غیرفعال است تا هیچ پیامی برای کاربران اپ اصلی فرستاده نشود.\'},true);\n');status('NEW HOPE 7 · HYBRID QA READY');setTimeout(()=>document.getElementById('nh7QaLoadStatus')?.remove(),1800);
